import{_ as t,o,c as a,a5 as n}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Research — How Google Docs Really Works & Its Application to FR 3.6.10","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-10-content-writting-view/research.md","filePath":"feature/content-task-workflow/3-6-10-content-writting-view/research.md"}'),i={name:"feature/content-task-workflow/3-6-10-content-writting-view/research.md"};function r(s,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="research-—-how-google-docs-really-works-its-application-to-fr-3-6-10" tabindex="-1">Research — How Google Docs Really Works &amp; Its Application to FR 3.6.10 <a class="header-anchor" href="#research-—-how-google-docs-really-works-its-application-to-fr-3-6-10" aria-label="Permalink to &quot;Research — How Google Docs Really Works &amp; Its Application to FR 3.6.10&quot;">​</a></h1><p>&gt; Background research for <a href="./spec.html">spec.md</a> / <a href="./plan.html">plan.md</a> (V3 — canvas-rendering + real-time OT). Not a spec, not an implementation plan — this is a synthesis of the technical knowledge behind the design decisions already locked in. &gt; &gt; 2026-10-01, updated 2026-10-05 after implementation (see §5).</p><h2 id="_1-why-a-separate-research-doc-was-needed" tabindex="-1">1. Why a Separate Research Doc Was Needed <a class="header-anchor" href="#_1-why-a-separate-research-doc-was-needed" aria-label="Permalink to &quot;1. Why a Separate Research Doc Was Needed&quot;">​</a></h2><p>FR 3.6.10 was originally understood as &quot;a Google-Docs-style rich-text editor&quot; — meaning an ordinary rich-text editor library (TipTap, already installed in <code>brandhub-web-dashboard</code>) running on <code>contentEditable</code>. Comparing that against how Google Docs actually works revealed the real architecture is fundamentally different — not a UI difference, but a difference in <strong>how content is displayed and how data is synced</strong>. This research captures that finding and the decisions that followed from it.</p><h2 id="_2-how-the-real-google-docs-works" tabindex="-1">2. How the Real Google Docs Works <a class="header-anchor" href="#_2-how-the-real-google-docs-works" aria-label="Permalink to &quot;2. How the Real Google Docs Works&quot;">​</a></h2><h3 id="_2-1-display-canvas-not-dom" tabindex="-1">2.1 Display: Canvas, Not DOM <a class="header-anchor" href="#_2-1-display-canvas-not-dom" aria-label="Permalink to &quot;2.1 Display: Canvas, Not DOM&quot;">​</a></h3><ul><li>Google Docs <strong>does not use HTML/DOM to display text</strong>. All content is drawn directly onto <code>&lt;canvas&gt;</code> elements — pixel-accurately.</li><li>Reason: Google Docs is a print-accurate WYSIWYG tool (<em>What You See Is What You Get</em> — A4/A5 page sizing, correct page breaks). Ordinary HTML is prone to line-shift differences across browsers/machines/fonts → page-count errors when printing or exporting to PDF. Canvas gives pixel-level control.</li><li>Before 2021, Google Docs still used a DOM-based architecture but <strong>had already written its own layout/editing engine</strong>, not relying on real <code>contentEditable</code> — it only faked the cursor with a <code>&lt;div&gt;</code> + CSS animation. From 2021 onward it fully migrated to canvas-based rendering (confirmed via public discussion from Google engineers on Hacker News).</li><li><strong>Virtualization</strong>: only a handful of <code>&lt;canvas&gt;</code> elements are created for the page(s) currently in the viewport. Scrolling reuses existing canvases to draw the new page&#39;s content, keeping hundred-page documents light. This is the standard windowing/virtualization pattern (similar to <code>react-window</code>), applied to canvas instead of a DOM list.</li></ul><h3 id="_2-2-input-offscreen-contenteditable-fake-cursor" tabindex="-1">2.2 Input: Offscreen <code>contentEditable</code> + Fake Cursor <a class="header-anchor" href="#_2-2-input-offscreen-contenteditable-fake-cursor" aria-label="Permalink to &quot;2.2 Input: Offscreen `contentEditable` + Fake Cursor&quot;">​</a></h3><ul><li>Since the text is pixels drawn on a canvas, not DOM text nodes, ordinary keyboard/focus events cannot be used directly on the canvas.</li><li>Google Docs uses a hidden <code>&lt;iframe&gt;</code> containing a <code>contenteditable</code> field, pushed off-screen (e.g. <code>translateX(-10000px)</code>) — solely to <strong>capture keystrokes, IME input, and paste</strong>. It displays nothing; it only receives input and forwards it into internal state.</li><li>The blinking cursor is actually a <code>&lt;div&gt;</code> animated with CSS, positioned using pixel coordinates computed from the canvas text layout.</li><li>Tables and text-selection highlighting are also drawn by the canvas itself — not via the native <code>window.getSelection()</code>.</li></ul><h3 id="_2-3-accessibility-a-parallel-hidden-dom-layer" tabindex="-1">2.3 Accessibility: A Parallel Hidden DOM Layer <a class="header-anchor" href="#_2-3-accessibility-a-parallel-hidden-dom-layer" aria-label="Permalink to &quot;2.3 Accessibility: A Parallel Hidden DOM Layer&quot;">​</a></h3><ul><li>Screen readers cannot read pixels on a canvas.</li><li>When accessibility mode is enabled, Google Docs quietly builds an additional hidden DOM region containing the real text, in parallel with the canvas, so screen readers can read it.</li></ul><h3 id="_2-4-data-sync-operational-transformation-ot-not-saving-a-file" tabindex="-1">2.4 Data Sync: Operational Transformation (OT), Not &quot;Saving a File&quot; <a class="header-anchor" href="#_2-4-data-sync-operational-transformation-ot-not-saving-a-file" aria-label="Permalink to &quot;2.4 Data Sync: Operational Transformation (OT), Not &quot;Saving a File&quot;&quot;">​</a></h3><ul><li>Google Docs <strong>does not save/sync a document as a text blob overwritten on every save</strong>. Every edit is a small <strong>operation</strong> (<code>insert</code>/<code>delete</code> at position X), written to a <strong>revision log</strong> — it never directly mutates the document&#39;s &quot;characters.&quot;</li><li>Core algorithm: a function usually written as <code>transform(opA, opB)</code> — takes two operations created against the same base state and returns adjusted versions that can be applied one after another while preserving both authors&#39; intent.</li><li>Example: you type &quot;hello&quot; at position 5, but someone else just deleted characters 2-4 → your operation is transformed: &quot;insert at position 5&quot; becomes &quot;insert at position 3&quot; (because two characters vanished before it).</li><li><strong>Persistence</strong>: periodic snapshots (the server stores one snapshot every few thousand operations) + the tail of the operation log — loading a document = the latest snapshot + replaying the remaining log, not a full replay from scratch every time.</li><li><strong>Why OT was chosen</strong>: the server already has to see every operation anyway, for access control, rendering, and storage — OT reuses that same data path instead of requiring a separate sync architecture.</li></ul><h3 id="_2-5-transport-long-polling-not-websocket" tabindex="-1">2.5 Transport: Long Polling, Not WebSocket <a class="header-anchor" href="#_2-5-transport-long-polling-not-websocket" aria-label="Permalink to &quot;2.5 Transport: Long Polling, Not WebSocket&quot;">​</a></h3><ul><li>Google Docs uses <strong>Long Polling</strong> via an HTTP request named <code>bind</code> (called the <em>Browser Channel</em>) — not WebSocket, Server-Sent Events, or WebRTC.</li><li>The main reason is historical: Google Docs began development around 2006 (as Writely), before WebSocket (standardized in 2011) existed. The Long Polling architecture was kept and incrementally optimized rather than rewritten.</li><li>Edit data is pushed continuously in small chunks, combined with OT — only position-based edit commands are sent, never the whole file.</li></ul><h3 id="_2-6-state-internal-naming" tabindex="-1">2.6 State &amp; Internal Naming <a class="header-anchor" href="#_2-6-state-internal-naming" aria-label="Permalink to &quot;2.6 State &amp; Internal Naming&quot;">​</a></h3><ul><li>Document state is kept in RAM, organized into formatting segments called <strong>&quot;runs&quot;</strong>.</li><li>When editing offline, Docs logs commands to <code>IndexedDB</code>, syncing once back online.</li><li>Google Docs&#39; internal codename is <strong>&quot;kix&quot;</strong> — visible through the <code>_kix</code> variable, CSS classes like <code>kix-editor</code>, <code>kix-canvas</code>, etc. (observed via DevTools, not official Google documentation).</li><li>The client source is minified/bundled with the <strong>Closure Compiler</strong> into one enormous object with nearly 20,000 keys renamed/shortened — unrelated to the architecture, just a build/optimization detail.</li></ul><h2 id="_3-applying-this-to-fr-3-6-10-—-what-stays-what-changes" tabindex="-1">3. Applying This to FR 3.6.10 — What Stays, What Changes <a class="header-anchor" href="#_3-applying-this-to-fr-3-6-10-—-what-stays-what-changes" aria-label="Permalink to &quot;3. Applying This to FR 3.6.10 — What Stays, What Changes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Real Google Docs aspect</th><th>Decision for FR 3.6.10</th><th>Reason</th></tr></thead><tbody><tr><td>Canvas rendering</td><td><strong>Kept as-is</strong></td><td>This is the literal user requirement — reproduce the real technique, not just the same UI</td></tr><tr><td>Offscreen <code>contentEditable</code> input capture</td><td><strong>Kept as-is</strong></td><td>Required for the canvas to receive keystrokes/IME — no other way to do this on the current web platform</td></tr><tr><td>Fake CSS cursor</td><td><strong>Kept as-is</strong></td><td>A forced consequence of not using DOM text — there is no native cursor on a canvas</td></tr><tr><td>Viewport-based virtualization</td><td><strong>Kept as-is</strong></td><td>Standard pattern, low cost, clear benefit (long documents stay light)</td></tr><tr><td>Shadow/off-screen DOM for accessibility</td><td><strong>Kept as-is</strong></td><td>Mandatory for accessibility — no other option when using canvas</td></tr><tr><td>Operational Transformation (sync)</td><td><strong>Kept in principle</strong>, <strong>implemented as CRDT (Yjs <code>Y.Text</code>)</strong>, not hand-written OT</td><td>Hand-written OT at production quality is very hard (well-known edge cases that are notoriously hard to debug — see <a href="./plan.html#6-technical-risks">plan.md §6</a>). Yjs uses CRDT — a different algorithm, but the same goal (convergence with no data loss, no locking) — lower risk since it&#39;s already battle-tested in production (Figma, Notion use similar mechanisms). This was a proposal as of 2026-10-01; confirmed as the actual implementation by 2026-10-05 — <code>Y.Text</code>&#39;s native <code>insert(index, text, attributes)</code>/<code>format(index, length, attributes)</code>/<code>toDelta()</code> turned out to double as the rich-text attribute engine too, so no separate formatting data structure was needed</td></tr><tr><td>Long Polling (Browser Channel <code>bind</code>)</td><td><strong>Changed to WebSocket</strong></td><td>The reason Google uses Long Polling is historical (2006, before WebSocket existed) — not a technical advantage worth preserving. WebSocket is the modern standard, Spring Boot already supports it (<code>spring-boot-starter-websocket</code>), with lower latency and simpler code</td></tr><tr><td>In-RAM &quot;runs&quot; state</td><td><strong>Equivalent</strong>: <code>TaskContentOperation</code> (operation log) + <code>TaskContentSnapshot</code></td><td>Different name, same principle: operation log + periodic snapshot, never saving full text on every save</td></tr><tr><td>IndexedDB offline queue</td><td><strong>Kept as-is</strong></td><td>Same need: the client must keep working while offline, syncing back on reconnect</td></tr><tr><td>Internal codename &quot;kix&quot;, Closure Compiler</td><td><strong>Not relevant</strong></td><td>Google&#39;s internal build/implementation details, no bearing on the design</td></tr></tbody></table><h2 id="_4-implementation-notes-added-2026-10-05-after-the-editor-was-actually-built" tabindex="-1">4. Implementation Notes (added 2026-10-05, after the editor was actually built) <a class="header-anchor" href="#_4-implementation-notes-added-2026-10-05-after-the-editor-was-actually-built" aria-label="Permalink to &quot;4. Implementation Notes (added 2026-10-05, after the editor was actually built)&quot;">​</a></h2><p>The canvas editor (<code>CanvasTextEditor.tsx</code> + <code>richText.ts</code> + <code>FormattingToolbar.tsx</code> in <code>brandhub-web-dashboard/src/pages/content-writing/components/</code>) is live, not just designed. A few decisions made during implementation extend beyond what §3&#39;s table anticipated:</p><ul><li><strong>Rich-text formatting lives entirely in <code>Y.Text</code> attributes</strong> — bold/italic/underline/strikethrough/color/highlight/font/size/link/align/listType are all per-character (or paragraph-scoped, for align/listType) attributes passed to <code>insert()</code>/<code>format()</code>. No separate formatting data structure was needed beyond what <code>Y.Text</code> already provides.</li><li><strong>List model</strong>: bullet/numbered lists are a paragraph-scoped attribute (<code>listType: &quot;bullet&quot; | &quot;number&quot;</code>), the same mechanism as paragraph alignment — not a separate block-type/outline structure. The bullet/number marker is a render-time-only overlay (drawn by <code>CanvasTextEditor</code>&#39;s paint step); it is never a stored character. Numbering for &quot;number&quot; lists is computed at render time by counting consecutive preceding paragraphs sharing <code>listType: &quot;number&quot;</code> — no index is persisted, so inserting or deleting list items never requires a renumbering pass or risks desyncing a stored number from reality.</li><li><strong>A real invariant had to be preserved carefully</strong>: the editor maintains two parallel line-wrap computations — a plain-text one (<code>wrapLines</code>, used for caret position/selection highlight/canvas height) and a rich-text one (<code>wrapRuns</code>, used only for painting styled text). Both MUST break lines at identical character offsets, or the caret and the painted glyphs desync. This ruled out narrowing the available width for list-indented paragraphs inside <code>wrapRuns</code> (which would have made its line breaks diverge from <code>wrapLines</code>&#39;) — the list indent is instead applied as a paint-time x-offset only, accepting a slightly-longer effective last line for list items as the trade-off.</li><li><strong>Paste-with-format</strong>: clipboard HTML is parsed with the browser&#39;s native <code>DOMParser</code> (no new dependency) into the same run/attribute model used internally. Scope was deliberately narrowed to bold/italic/underline/link/listType — font, color, and size from the clipboard source are dropped so pasted content always matches this editor&#39;s own design rather than carrying over arbitrary external styling.</li><li><strong>Layout constants were tuned toward Google Docs&#39; real defaults but not matched exactly</strong>: font is Arial 11pt (rendered at 15px, rounded for crisp canvas glyphs) with 1.15 line-height, matching Docs precisely. Page margin is Docs&#39; real 2.54cm (~96px @96dpi) vertically, but a smaller 32px horizontally — the canvas here is a responsive-width panel, not a fixed-width printable page, so a full 96px side margin would consume too much space on narrow screens. This is a deliberate, documented trade-off, not an oversight.</li><li>Undo/redo uses Yjs&#39;s own <code>UndoManager</code> scoped to the editor&#39;s <code>Y.Text</code>, with <code>captureTimeout: 500</code> — local edits within 500ms of each other coalesce into one undo step (including every run of a single multi-styled paste, since they&#39;re all inserted inside one <code>yDoc.transact()</code> call).</li></ul><h2 id="_5-limitations-of-this-research" tabindex="-1">5. Limitations of This Research <a class="header-anchor" href="#_5-limitations-of-this-research" aria-label="Permalink to &quot;5. Limitations of This Research&quot;">​</a></h2><ul><li>The observations about <code>kix</code>, the hidden DOM structure, and the offscreen iframe are <strong>external observations</strong> (via DevTools, community technical write-ups, and public discussion from Google engineers) — not official architecture documentation from Google. Google has not published Docs&#39; full source code or technical spec.</li><li>Google&#39;s actual <code>transform()</code> algorithm (handling rich-text formatting, not just plain-text insert/delete) has not been published in detail — the OT design for rich text in <code>plan.md</code> will need to be designed independently; it cannot be copied from an original source.</li><li>There is no real benchmark of latency/performance between Long Polling (the original) and WebSocket (the chosen replacement) in BrandHub&#39;s specific context — the decision is based on architectural reasoning (simpler, more modern), not on actual measurement.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://news.ycombinator.com/item?id=27129858" target="_blank" rel="noreferrer">Google Docs will now use canvas based rendering — Hacker News discussion</a></li><li><a href="https://www.libhunt.com/posts/255745-google-docs-will-move-to-canvas-based-rendering-instead-of-dom" target="_blank" rel="noreferrer">Google Docs will move to canvas based rendering instead of DOM</a></li><li><a href="https://www.linkedin.com/pulse/design-google-docs-crdt-operational-transformation" target="_blank" rel="noreferrer">Design Google Docs — CRDT &amp; Operational Transformation</a></li><li><a href="https://en.wikipedia.org/wiki/Operational_transformation" target="_blank" rel="noreferrer">Operational transformation — Wikipedia</a></li><li><a href="https://www.enjoyalgorithms.com/blog/design-google-docs/" target="_blank" rel="noreferrer">Google Docs System Design — EnjoyAlgorithms</a></li><li><a href="https://newsletter.systemdesign.one/p/how-does-google-docs-work" target="_blank" rel="noreferrer">How Does Google Docs Work — The System Design Newsletter</a></li><li><a href="https://levelop.dev/blog/google-docs-with-25m-concurrent-editors-conflict-resolution-architecture" target="_blank" rel="noreferrer">How Operational Transformation Powers Google Docs</a></li><li><a href="https://systemdr.systemdrd.com/p/crdts-vs-operational-transformation" target="_blank" rel="noreferrer">CRDTs vs. Operational Transformation: How Google Docs Handles Collaborative Editing</a></li><li>A technical analysis write-up the user provided in conversation (2026-10-01) — describing canvas rendering, the offscreen iframe, the &quot;kix&quot; internal codename, the Long Polling <code>bind</code> endpoint, and the IndexedDB offline log.</li></ul>',26)])])}const p=t(i,[["render",r]]);export{u as __pageData,p as default};
